export const ANIMALS = [null,{name:'Rat',zh:'鼠',emoji:'🐭',tip:'I can swim and catch the elephant on land!'},{name:'Cat',zh:'猫',emoji:'🐱',tip:'I can catch rats and other cats.'},{name:'Wolf',zh:'狼',emoji:'🐺',tip:'I can catch animals ranked 3 or less.'},{name:'Dog',zh:'狗',emoji:'🐶',tip:'I can catch animals ranked 4 or less.'},{name:'Leopard',zh:'豹',emoji:'🐆',tip:'I can catch animals ranked 5 or less.'},{name:'Tiger',zh:'虎',emoji:'🐯',tip:'I can leap across rivers, unless a rat blocks my way!'},{name:'Lion',zh:'狮',emoji:'🦁',tip:'I can leap across rivers, unless a rat blocks my way!'},{name:'Elephant',zh:'象',emoji:'🐘',tip:'I am the strongest, but watch out for the little rat!'}];
export const water=(r,c)=>r>=3&&r<=5&&[1,2,4,5].includes(c);
export function terrain(r,c){if(c===3&&(r===0||r===8))return {type:'den',owner:r===0?'blue':'orange'};if(((r===0||r===8)&&(c===2||c===4))||((r===1||r===7)&&c===3))return {type:'trap',owner:r<4?'blue':'orange'};return {type:water(r,c)?'water':'land'};}
export function initialState(){const pieces=[];const setup=[[0,0,7],[0,6,6],[1,1,4],[1,5,2],[2,0,1],[2,2,5],[2,4,3],[2,6,8]];for(const [r,c,rank]of setup){pieces.push({id:'blue-'+rank,team:'blue',rank,r,c});pieces.push({id:'orange-'+rank,team:'orange',rank,r:8-r,c:6-c});}return {pieces,turn:'orange',winner:null,reason:'',moves:0,last:null};}
export function canCapture(p,t){if(water(p.r,p.c)!==water(t.r,t.c))return false;const trap=terrain(t.r,t.c);if(trap.type==='trap'&&trap.owner===p.team)return true;if(p.rank===1&&t.rank===8)return true;if(p.rank===8&&t.rank===1)return false;return p.rank>=t.rank;}
export function legalMoves(state,id){const p=state.pieces.find(p=>p.id===id);if(!p||state.winner)return [];const moves=[];for(const [dr,dc]of [[-1,0],[1,0],[0,-1],[0,1]]){let r=p.r+dr,c=p.c+dc;if(r<0||r>8||c<0||c>6)continue;if(water(r,c)&&p.rank!==1){if(p.rank!==6&&p.rank!==7)continue;let blocked=false;while(water(r,c)){if(state.pieces.some(x=>x.r===r&&x.c===c))blocked=true;r+=dr;c+=dc;}if(blocked)continue;}const tile=terrain(r,c);if(tile.type==='den'&&tile.owner===p.team)continue;const target=state.pieces.find(x=>x.r===r&&x.c===c);if(target&&(target.team===p.team||!canCapture(p,target)))continue;moves.push({r,c,capture:target?.id??null,jump:Math.abs(p.r-r)+Math.abs(p.c-c)>1});}return moves;}
export function move(state,id,r,c){const p=state.pieces.find(x=>x.id===id);if(!p||p.team!==state.turn||!legalMoves(state,id).some(m=>m.r===r&&m.c===c))return null;const next=structuredClone(state);const captured=next.pieces.find(x=>x.r===r&&x.c===c);next.pieces=next.pieces.filter(x=>x.id!==captured?.id);const animal=next.pieces.find(x=>x.id===id);next.last={from:{r:p.r,c:p.c},to:{r,c},rank:p.rank,team:p.team,captured:captured?.rank??null};animal.r=r;animal.c=c;next.moves++;next.turn=p.team==='orange'?'blue':'orange';if(terrain(r,c).type==='den'){next.winner=p.team;next.reason='You reached the other den!';}else if(!next.pieces.some(x=>x.team===next.turn)){next.winner=p.team;next.reason='You caught all the other animals!';}else if(!next.pieces.some(x=>x.team===next.turn&&legalMoves(next,x.id).length)){next.winner=p.team;next.reason='The other team has no moves left.';}return next;}
